<?php declare(strict_types=1); ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My bookings</title><style>body{font-family:var(--villa-font-body);background:#f6f8f6;color:var(--villa-text);margin:0}.wrap{max-width:1000px;margin:35px auto;padding:0 18px}.item{background:white;border:1px solid #e7ece8;border-radius:13px;padding:18px;margin:12px 0;display:flex;justify-content:space-between;gap:15px}.muted{color:var(--villa-text);}.tag{background:#eef5ef;padding:6px 10px;border-radius:20px;font-size:var(--villa-body-size);height:max-content}@media(max-width:600px){.item{display:block}}</style><?php require APP_ROOT . '/views/site/partials/account-theme.php'; ?></head><body><main class="wrap"><h1>My bookings</h1><p class="muted">Your booking requests and their current status.</p><?php foreach($bookings as $booking): ?><article class="item"><div><strong><?= e($booking['title']) ?></strong><p class="muted"><?= e($booking['city']) ?> · <?= e(date('d.m.Y',strtotime($booking['check_in']))) ?> – <?= e(date('d.m.Y',strtotime($booking['check_out']))) ?> · <?= (int)$booking['guests'] ?> guests</p><small><?= e($booking['booking_code']) ?></small><p><a href="<?= e(app_url('/account/messages/' . (int)$booking['id'])) ?>">Messages</a></p><?php if($booking['status']==='completed' && empty($booking['has_review'])): ?><p><a href="<?= e(app_url('/account/reviews/' . (int)$booking['id'])) ?>">Rate out of 10</a></p><?php elseif(!empty($booking['has_review'])): ?><p class="muted">Your review was submitted and is awaiting approval or publication</p><?php endif; ?></div><div><span class="tag"><?= e($booking['status']) ?></span><p><strong><?= e(number_format((float)$booking['total'],0,',','.')) ?> <?= e($booking['currency']) ?></strong></p><?php if(!empty($booking['has_paid_payment'])): ?><p class="muted">Payment verified</p><?php elseif($booking['status']==='pending'): ?><?php if(($booking['manual_payment_status']??'')==='pending'): ?><p class="muted">Bank transfer notification is under review</p><?php else: ?><p><a href="<?= e(app_url('/checkout/'.rawurlencode((string)$booking['booking_code']))) ?>">Pay or report a bank transfer</a></p><?php endif; ?><?php endif; ?></div></article><?php endforeach; ?><?php if(!$bookings): ?><p>You have no bookings yet.</p><?php endif; ?><p><a href="<?= e(app_url('/account/notifications')) ?>">Notifications</a> · <a href="<?= e(app_url('/')) ?>">Discover new properties</a></p><?php require APP_ROOT . '/views/site/partials/logout-button.php'; ?></main></body></html>